use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar. Algorithm: Howard Hinnant's `civil_from_days`.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Formats a Unix timestamp (seconds, UTC) as `YYYY-MM-DD`, always 10 bytes.
fn utc_date(secs: u64) -> String {
    let days = (secs / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    // Four-digit years only. Timestamps past 9999-12-31 are unreachable for a
    // real wall clock; clamping keeps the `len(date) == 10` ensure true anyway.
    let y = y.clamp(0, 9_999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: utc_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
